// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // General rule: For any calldata passed to initialize, the reference implementation always sets
    // baseToken == _baseToken after initialize returns successfully. The mutant conditionally skips
    // assigning baseToken when it was zero, causing a mismatch for some fuzz inputs. We fuzz the
    // _baseToken parameter (as address) and other initializer params so the fuzzer can find a case
    // where the mutant behaves differently.
    function testFuzz_property(address fuzz_baseToken, address fuzz_nft, uint128 fuzz_vBase, uint128 fuzz_vNft, uint56 fuzz_changeFee, uint16 fuzz_feeRate, bytes32 fuzz_merkleRoot, bool fuzz_useOracle, bool fuzz_payRoyalties) public {
        // Keep inputs wide but constrain feeRate to valid range to avoid revert FeeRateTooHigh from both versions
        // We allow feeRate up to 5000 inclusive. If fuzz_feeRate > 5000, the call should revert in both impls; we avoid that.
        if (fuzz_feeRate > 5000) fuzz_feeRate = 5000;

        // Ensure contract is not yet initialized
        // Call initialize and capture whether it returns (ok == true) or reverts (ok == false)
        bool ok;
        try c.initialize(fuzz_baseToken, fuzz_nft, fuzz_vBase, fuzz_vNft, fuzz_changeFee, fuzz_feeRate, fuzz_merkleRoot, fuzz_useOracle, fuzz_payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize succeeded, then baseToken() must equal the _baseToken argument passed in.
        // This is the one universal property the reference satisfies for every admissible input and
        // the mutant violates for some inputs (it may leave baseToken unchanged).
        if (ok) {
            assertTrue(c.baseToken() == fuzz_baseToken, "baseToken must equal the _baseToken passed to initialize");
        } else {
            // If initialize reverted, we cannot assert on baseToken (initialize didn't complete);
            // but the universal property only applies when initialize completes, so simply succeed.
            assertTrue(true);
        }
    }
}

