    // We keep domain wide: any addresses except address(0) for nft is allowed, and baseToken may be any address (including zero).
    function testFuzz_property(address _baseToken, address _nft) public {
        // keep nft non-zero to be a realistic token contract address (but allow zero baseToken too)
        vm.assume(_nft != address(0));

        // ensure we call initialize from a neutral caller
        // call initialize and observe whether baseToken gets set to the supplied _baseToken
        bool ok;
        try c.initialize(_baseToken, _nft, uint128(1), uint128(1), uint56(0), uint16(0), bytes32(0), false, false) {
