pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed: caller address and a baseToken candidate
    function testFuzz_property(address caller, address baseTokenCandidate) public {
        // keep wide but avoid zero-address for caller (prank expects an EOA-like address)
        vm.assume(caller != address(0));

        // First initialize should succeed for both reference and mutant
        vm.prank(caller);
        // call with arbitrary other params; these aren't crucial for this property
        c.initialize(baseTokenCandidate, address(0), 1, 1, 1, 1, bytes32(0), false, false);

        // Second initialize must ALWAYS revert (AlreadyInitialized) on the correct contract
        // We test whether a second call returns (succeeds) or reverts.
        bool ok;
        vm.prank(caller);
        try c.initialize(baseTokenCandidate, address(0), 2, 2, 2, 2, bytes32(1), true, true) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: reference contract always reverts on second initialize -> ok == false for all inputs.
        // The mutant can sometimes let the second call succeed (ok == true) due to conditional baseToken assignment.
        assertTrue(!ok);
    }
}

