pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz parameters: a caller address and a baseToken candidate address to set
    function testFuzz_property(address caller, address newBaseToken) public {
        // keep addresses wide but not zero for caller (we need an EOA to prank from)
        vm.assume(caller != address(0));

        // Step 1: simulate a pre-existing nonzero baseToken by calling initialize once from a helper owner
        // We deploy a helper that calls initialize on C to set some pre-seed baseToken value (seedBase)
        PreSeeder pre = new PreSeeder(c);
        address seedBase = address(0x1234);

        // Pre-seed c with a nonzero baseToken so that mutant's "only set if baseToken==0" path matters
        vm.prank(address(pre));
        pre.seed(seedBase);

        // Ensure that pre-seeding indeed produced a nonzero baseToken (observable in both ref and mutant)
        assertTrue(c.baseToken() != address(0));

        // Now call initialize again from 'caller' with fuzzed newBaseToken
        // The reference implementation will always set baseToken = newBaseToken (regardless of previous value)
        // The mutant may skip setting baseToken if it checks baseToken==address(0) before assigning.
        vm.prank(caller);
        bool ok;
        try c.initialize(newBaseToken, address(0), 0, 0, 0, 0, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if initialize returned (ok==true), then c.baseToken() must equal the provided newBaseToken.
        // The reference satisfies this for all inputs; the mutant will sometimes return ok==true but leave baseToken unchanged,
        // making this assertion fail for some fuzzed newBaseToken values.
        if (ok) {
            assertTrue(c.baseToken() == newBaseToken);
        }
    }
}

// Helper contract that calls initialize on target C to pre-seed baseToken
contract PreSeeder {
    C target;
    constructor(C _target) { target = _target; }
    function seed(address b) external {
        // call initialize with some params to set baseToken to b
        target.initialize(b, address(0), 0, 0, 0, 0, bytes32(0), false, false);
    }
}

