pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzzed params: baseToken address and nft address (we will deploy a malicious NFT contract at the fuzzed nftAddress
    // by ignoring the provided address and instead deploying a helper; but we keep baseToken as a fuzzed address to allow
    // the fuzzer to find differing behaviors). We also fuzz feeRate to be within admissible bounds.
    function testFuzz_property(address baseTokenAddr, uint16 feeRate) public {
        // Keep feeRate within admissible bounds [0, 5000] (reference enforces >5000 revert)
        vm.assume(feeRate <= 5000);

        // We'll deploy a malicious ERC721 that in safeTransferFrom re-enters C.initialize when ownership is being set
        // to try and observe intermediate state. The mutant moves baseToken assignment later, so a reentrant call during
        // initialize could observe a different baseToken compared to the provided one. We need an address with code.
        MaliciousNFT mal = new MaliciousNFT(address(c));

        // Prepare parameters for initialize. We fuzzed baseTokenAddr and feeRate. Other parameters fixed but valid.
        address _baseToken = baseTokenAddr;
        address _nft = address(mal);
        uint128 _virtualBaseTokenReserves = 1;
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 1;
        uint16 _feeRate = feeRate;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        // The malicious NFT will attempt to re-enter c.initialize during the call flow that occurs when
        // the factory in the real system would safeTransfer NFTs into a pool during create. Here we directly
        // call initialize on c; to trigger the adversarial path we make the malicious NFT's onERC721Received
        // attempt a read of baseToken via public getter and store it internally so we can compare after initialize.

        // Ensure the mal contract knows what parameters we will provide so it can decide when to reenter.
        mal.setTargetParams(_baseToken);

        // Call initialize. We wrap in try/catch to convert revert into a boolean if needed, but the property we assert
        // is about final state when initialize returns successfully. If initialize reverts, we consider that case
        // outside the universal property (the reference also reverts on invalid inputs); so we only assert when it succeeds.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!ok) return; // if initialize reverted, nothing to assert about final state (both may revert for invalid inputs)

        // Exactly one assertion: the reference should satisfy that c.baseToken() equals the _baseToken we passed in.
        // The mutant can be made to fail this by the reentrant behavior in MaliciousNFT that observes/affects
        // intermediate state during initialize; the fuzzer can find baseTokenAddr values that trigger the difference.
        assertTrue(c.baseToken() == _baseToken);
    }
}

// Minimal adversarial helper: a malicious ERC721-like receiver that tries to observe/trigger reentrancy.
// It implements onERC721Received and when called it will read c.baseToken() and store it — in mutant runs
// this can observe an intermediate value; but our final assertion inspects the final stored public getter.
contract MaliciousNFT {
    address public pool;
    address public observedBaseToken;
    address public expectedBaseToken;

    constructor(address _pool) {
        pool = _pool;
    }

    function setTargetParams(address _expectedBaseToken) external {
        expectedBaseToken = _expectedBaseToken;
    }

    // mimic ERC721 token receiver hook to be used in any safeTransferFrom path
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        // read baseToken from pool during the transfer; this implements the adversarial observation
        observedBaseToken = C(pool).baseToken();
        return this.onERC721Received.selector;
    }
}

