    // triggers a callback that re-enters initialize or otherwise observes state, it may cause
    // baseToken != _baseToken after initialize returns. We fuzz the _baseToken and an NFT tokenId
    // and deploy a malicious NFT contract to simulate the adversarial behaviour.
    function testFuzz_property(address fuzzBaseToken, uint256 fuzzTokenId) public {
        // keep baseToken in a realistic address range (non-zero) but allow zero as well
        // (we do not exclude any realistic case)
        // Deploy a malicious ERC721 that will, during safeTransferFrom into the pool in Factory.create path,
        // not needed here — but initialize itself doesn't transfer NFTs. To exercise the mutant's
        // ordering vulnerability, we simulate an attacker NFT contract that, when queried via
        // ownerOf or when safeTransferFrom is called later in flows, could re-enter. However initialize
        // sets nft state and then emits Initialize. The mutation moves baseToken assignment later, so
        // we craft a malicious NFT whose onERC721Received (called by PrivatePoolMetadata.safeTransferFrom etc.)
        // will call back into c.initialize to try to observe the differing ordering. We'll fuzz parameters
        // but use the malicious NFT as the nft address parameter to initialize.

        // Deploy malicious NFT receiver that will attempt to re-enter initialize during token transfer
        MaliciousNFT mal = new MaliciousNFT(address(c));

        // Prepare parameters: use fuzzBaseToken and mal as nft
        address _baseToken = fuzzBaseToken;
        address _nft = address(mal);
        uint128 _virtualBaseTokenReserves = uint128(1);
        uint128 _virtualNftReserves = uint128(1);
        uint56 _changeFee = uint56(0);
        uint16 _feeRate = uint16(100);
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        // The reentrant call path: our MaliciousNFT will try to call initialize again on the pool
        // during an ERC721 transfer. To let that happen, we first call initialize once with the malicious
        // nft address so that if the mutant assigns nft early, the malicious contract may observe state.
        // We perform the call from this contract (an EOA-like actor in tests).

        // Use try/catch to observe whether initialize succeeded; we assert that if it succeeded,
        // then c.baseToken() equals the supplied _baseToken. This holds for the reference, but the mutant
        // can be forced (by the reentrancy inside MaliciousNFT) to break it for some fuzzed inputs.

        bool ok;
        try c.initialize(
