            // but we must make a single assertTrue reading c: in this case we assert that initialized is false
            // (initialize reverted so contract must remain uninitialized).
            assertTrue(!c.initialized());
        }
    }
}

// Minimal malicious ERC721 that attempts to re-enter C.initialize during a safe transfer callback
contract MaliciousNFT {
    address pool;
    constructor(address _pool) {
        pool = _pool;
    }

    // ERC721 receiver hook: when onERC721Received is called, attempt to re-enter initialize with a different baseToken
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        // attempt to re-enter initialize with a different baseToken to try to exploit ordering
        // We ignore success/failure; just call to create possible divergence in mutant.
        // Provide mostly-default params; use this contract as nft to maximize chance of hitting mutant ordering.
        // We call in a try/catch to avoid bubbling failures.
        try C(payable(pool)).initialize(address(0xdead), address(this), 1, 1, 0, 100, bytes32(0), false, false) {
        } catch {}
        return C.onERC721Received.selector;
    }

    // Minimal ERC721-like functions used by C: ownerOf and safeTransferFrom are expected in flows; implement simple stubs
    function ownerOf(uint256) external view returns (address) { return address(this); }

    function safeTransferFrom(address, address, uint256) external {}
}

