pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // General rule to check: the second call to initialize(...) MUST revert (re-initialization is forbidden).
    // We fuzz all initialization parameters so the fuzzer can find a case where the buggy mutant allows re-init.
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // keep feeRate admissible (constructor enforces >5000 revert)
        // but allow fuzzer to try values including >5000; in that case initialize should revert on first call
        // We only assume feeRate within uint16 (already) and no other restrictions.

        bool firstOk;
        // First initialization attempt: try/catch to record whether it succeeded.
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // If the first call reverted due to invalid feeRate (>5000), the correct contract reverts and nothing more to check.
        // In that case the property "second call reverts" is vacuously true because no successful first init to protect.
        if (!firstOk) {
            // Assert that initialized is false when first init failed
            assertTrue(!c.initialized());
            return;
        }

        // At this point first initialization succeeded; by invariant, initialized must be true.
        assertTrue(c.initialized());

        // Now attempt a second initialize with (possibly different) fuzzed parameters to detect re-initialization vulnerability.
        bool secondOk;
        try c.initialize(
            address(uint160(uint256(keccak256(abi.encodePacked(_baseToken, _nft, _feeRate, _merkleRoot, block.timestamp))))), // fuzz-influenced different values
            address(uint160(uint256(keccak256(abi.encodePacked(_nft, _baseToken, _changeFee))))),
            _virtualBaseTokenReserves + 1,
            _virtualNftReserves + 1,
            _changeFee,
            _feeRate,
            bytes32(keccak256(abi.encodePacked(_merkleRoot, _useStolenNftOracle))),
            !_useStolenNftOracle,
            !_payRoyalties
        ) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // The correct contract always prevents re-initialization: second call must revert -> secondOk == false.
        // The mutant removes the revert allowing secondOk == true for some inputs. We assert the property that second call reverts.
        assertTrue(!secondOk);
    }
}
